import json, re, os

with open('deliverable/risk_assessment.json') as f:
    d = json.load(f)
with open('library/INDEX.md') as f:
    idx = f.read()

allowed = set(re.findall(r'\|\s*`([A-Za-z0-9_\-\.]+\.md)`', idx)) or set(re.findall(r'`([A-Za-z0-9_\-\.]+\.md)`', idx))
print('INDEX set:', sorted(allowed))
actual = {f for f in os.listdir('library') if f.endswith('.md') and f != 'INDEX.md'}
assert allowed == actual, (allowed, actual)

cited = set()
def walk(x, path=''):
    if isinstance(x, dict):
        for k, v in x.items(): walk(v, path+'/'+k)
    elif isinstance(x, list):
        for i, v in enumerate(x): walk(v, f'{path}[{i}]')
    elif isinstance(x, str):
        cited.update(m for m in re.findall(r'(?:library/)?([A-Za-z0-9_\-]+\.md)', x) if m != 'INDEX.md')
walk(d)
bad = sorted(c for c in cited if c not in allowed)
print('Citations found in JSON:', sorted(cited))
print('Outside INDEX:', bad if bad else 'NONE')
EOF

